import pandas as pd, numpy as np
path = "/Users/mac/Documents/学习/找工作/SolveX/bench/sessions/r6-c3-quality-mwojlyns/data/2026_MCM_Problem_C_Data.csv"
df = pd.read_csv(path)

def to_num(v):
    try: return float(v)
    except: return np.nan

# judge4 usage by season: any positive judge4 score?
print("judge4 usage by season (count of positive cells):")
for s, g in df.groupby("season"):
    c4 = [f"week{w}_judge4_score" for w in range(1,12)]
    mat = g[c4].map(to_num)
    n_pos = int((mat>0).sum())
    if n_pos>0: print(f"  season {s}: {n_pos} positive judge4 cells")

